#!/usr/bin/env node
// The registry stand-in's pnpm, NOT pnpm: it says it ran, with its arguments, and answers no
// `pnpm config` question, so the guard falls back to the npmrc chain. A cell installs it to show the
// shim reaching a pnpm the agent installed into ~/.local/bin; pnpm's own forms are the host's units.
if (process.argv[2] === 'config') process.exit(1);
console.log('stand-in pnpm ran: ' + process.argv.slice(2).join(' '));
